import {readFileSync,readdirSync,statSync,existsSync} from 'node:fs';
import {resolve,dirname} from 'node:path';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {parse} from 'yaml';
const root='skills/varhandles-and-memory-ordering';
const artifacts='C:/Users/robso/AppData/Local/Temp/skills-wave2-validation-Bu1zNV/varhandles-and-memory-ordering-check';
const walk=p=>readdirSync(p).flatMap(n=>{const path=p+'/'+n;return statSync(path).isDirectory()?walk(path):[path]});
const sha=p=>createHash('sha256').update(readFileSync(p)).digest('hex');
const manifest=parse(readFileSync(root+'/skill.yaml','utf8'));
const front=parse(readFileSync(root+'/SKILL.md','utf8').split('---')[1]);
const baseline=JSON.parse(readFileSync('docs/skill-validation/wave2-2026-10-16/baseline.json','utf8'));
const issues=[];
const files=walk(root).map(path=>({path,assignmentSha256:baseline.allFiles[path],sha256:sha(path),unchanged:baseline.allFiles[path]===sha(path)}));
const links=[];
for(const {path:file} of files.filter(f=>f.path.endsWith('.md'))){
  for(const match of readFileSync(file,'utf8').matchAll(/\[[^\]]*\]\((?:<([^>]+)>|([^\s)]+))\)/g)){
    const href=match[1]??match[2];
    if(/^(?:https?:|mailto:|#)/.test(href)) continue;
    links.push({file,href,exists:existsSync(resolve(dirname(file),decodeURIComponent(href.split('#')[0])))});
  }
}
const status=execFileSync('git',['status','--short','--',root],{encoding:'utf8'});
const staged=execFileSync('git',['diff','--cached','--',root],{encoding:'utf8'});
const unstaged=execFileSync('git',['diff','--',root],{encoding:'utf8'});
const descriptionsMatch=front.description.trim()===manifest.description.trim();
if(front.name!==manifest.name||!descriptionsMatch||manifest.version!=='1.2.4') issues.push('metadata mismatch');
if(files.some(f=>!f.unchanged)||status||staged||unstaged)issues.push('unexpected package change');
if(links.some(l=>!l.exists))issues.push('missing local link');
const peers=[...(manifest.dependencies??[]).map(d=>d.name),...(manifest.suggests??[])].map(name=>({name,exists:existsSync('skills/'+name+'/SKILL.md')}));
if(peers.some(p=>!p.exists))issues.push('missing declared peer');
console.log(JSON.stringify({version:manifest.version,descriptionsMatch,status,staged,unstaged,files,localLinks:links,declaredPeers:peers,artifacts:walk(artifacts).map(path=>({path,sha256:sha(path)})),issues},null,2));
if(issues.length)process.exitCode=1;
'@ | node --input-type=module

