import java.lang.invoke.MethodHandles;
import java.lang.invoke.VarHandle;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public final class ReadyFlag {
    private static final VarHandle VIEW =
            MethodHandles.byteBufferViewVarHandle(int[].class, ByteOrder.LITTLE_ENDIAN);
    private final ByteBuffer storage = ByteBuffer.allocate(32);

    public ReadyFlag() {
        if (!VIEW.isAccessModeSupported(VarHandle.AccessMode.SET_RELEASE)
                || !VIEW.isAccessModeSupported(VarHandle.AccessMode.GET_ACQUIRE)) {
            throw new UnsupportedOperationException("Required readiness access mode unavailable");
        }
    }

    public void publish() {
        VIEW.setRelease(storage, 0, 1);
    }

    public boolean observed() {
        return (int) VIEW.getAcquire(storage, 0) == 1;
    }

    public static void main(String[] args) {
        ReadyFlag flag = new ReadyFlag();
        flag.publish();
        System.out.println(flag.observed());
    }
}

